package com.example.benchmark.domain;

/**
 * Domain object representing an item for benchmark testing.
 * Maps to the benchmark_items table in Oracle database.
 */
public class Item {

    /**
     * Primary key, generated by benchmark_items_seq sequence.
     */
    private Long id;

    /**
     * Item name (VARCHAR2(100), NOT NULL).
     * Format: "Item-" + 8-digit number (e.g., Item-00000001)
     */
    private String name;

    /**
     * Item description (VARCHAR2(500)).
     */
    private String description;

    /**
     * Item quantity (NUMBER(10), DEFAULT 0).
     * Random value between 0-999.
     */
    private int quantity;

    /**
     * Item price (NUMBER(15,2), DEFAULT 0).
     * Random value between 0-10000 with 2 decimal places.
     */
    private double price;

    public Item() {
    }

    public Item(String name, String description, int quantity, double price) {
        this.name = name;
        this.description = description;
        this.quantity = quantity;
        this.price = price;
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public int getQuantity() {
        return quantity;
    }

    public void setQuantity(int quantity) {
        this.quantity = quantity;
    }

    public double getPrice() {
        return price;
    }

    public void setPrice(double price) {
        this.price = price;
    }

    @Override
    public String toString() {
        return "Item{" +
                "id=" + id +
                ", name='" + name + '\'' +
                ", description='" + description + '\'' +
                ", quantity=" + quantity +
                ", price=" + price +
                '}';
    }
}
